package io.github.benbagwell.dominoprint.adapter;

import io.github.benbagwell.dominoprint.formula.*;
import io.github.benbagwell.dominoprint.render.PrintFormCompiler;
import java.time.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

class DominoImporterTest {
    public static class Column {final int index;final boolean sorted;boolean recycled;Column(int i,boolean s){index=i;sorted=s;}public int getColumnValuesIndex(){return index;}public boolean isSorted(){return sorted;}public void recycle(){recycled=true;}}
    public static class NativeDate {int recycled;public String getDateOnly(){return "10/10/2026";}public String getTimeOnly(){return "";}public String getLocalTime(){return "10/10/2026";}public boolean isDST(){return false;}public java.util.Date toJavaDate(){return java.util.Date.from(Instant.parse("2026-10-10T04:00:00Z"));}public void recycle(){recycled++;}}
    public static class Entry {boolean recycled;final NativeDate date=new NativeDate(),unused=new NativeDate();final Document doc=new Document();public boolean isDocument(){return true;}public Vector<Object> getColumnValues(){return new Vector<>(List.of(date,date,unused));}public Document getDocument(){return doc;}public void recycle(){recycled=true;}}
    public static class Entries {boolean recycled;final Entry entry=new Entry();public Entry getFirstEntry(){return entry;}public Entry getNextEntry(Entry current){return null;}public void recycle(){recycled=true;}}
    public static class View {boolean autoUpdate=true;final Vector<Column> columns=new Vector<>(List.of(new Column(65535,false),new Column(0,true),new Column(1,false)));final Entries entries=new Entries();public boolean isAutoUpdate(){return autoUpdate;}public void setAutoUpdate(boolean value){autoUpdate=value;}public Database getParent(){return new Database();}public String getName(){return "Cached";}public Vector<String> getAliases(){return new Vector<>();}public Vector<Column> getColumns(){return columns;}public Entries getAllEntries(){return entries;}}
    @Test void excludesConstantColumnsPreservesPartialDatesAndRecyclesAliasedValuesOnce(){var view=new View();var captured=new DominoImporter(new Session()).captureView(view,ZoneId.of("America/New_York"));assertEquals(1,captured.rows().size());var date=(io.github.benbagwell.dominoprint.model.DominoDateTime)captured.rows().get(0).firstSortedKey().elements().get(0);assertEquals(LocalDate.of(2026,10,10),date.date().orElseThrow());assertTrue(date.time().isEmpty());assertTrue(date.offset().isEmpty());assertTrue(view.autoUpdate);assertEquals(1,view.entries.entry.date.recycled);assertEquals(1,view.entries.entry.unused.recycled);assertTrue(view.columns.stream().allMatch(c->c.recycled));assertTrue(view.entries.recycled);assertTrue(view.entries.entry.recycled);assertTrue(view.entries.entry.doc.recycled);}
    @Test void restoresAutoUpdateAndRecyclesViewHandlesOnExportFailure(){var view=new View();var session=new Session();session.fail=true;assertThrows(DominoImportException.class,()->new DominoImporter(session).captureView(view));assertTrue(view.autoUpdate);assertTrue(view.entries.recycled);assertTrue(view.entries.entry.recycled);assertTrue(view.entries.entry.doc.recycled);assertEquals(1,view.entries.entry.date.recycled);}
    public static class Database {public String getServer(){return "Server/Acme";}public String getFilePath(){return "apps/data.nsf";}public String getReplicaID(){return "REPLICA";}public String getTitle(){return "Data";}}
    public static class Document {boolean recycled;int sequence=1;final Database database=new Database();public Database getParentDatabase(){return database;}public void recycle(){recycled=true;}String dxl(boolean raw){return "<"+(raw?"note":"document")+"><noteinfo unid='A' sequence='"+sequence+"'/><item name='Subject'><text>captured</text></item></"+(raw?"note":"document")+">";}}
    public static class Exporter {boolean recycled,raw,attachmentsOmitted=true,picturesOmitted=true,oleOmitted=true;final Session session;Exporter(Session session){this.session=session;}public void setOutputDOCTYPE(boolean value){}public void setForceNoteFormat(boolean value){raw=value;}public void setRichTextOption(int value){}public void setOmitRichtextAttachments(boolean value){attachmentsOmitted=value;}public void setOmitRichtextPictures(boolean value){picturesOmitted=value;}public void setOmitOLEObjects(boolean value){oleOmitted=value;}public void setOmitMiscFileObjects(boolean value){}public void setConvertNotesBitmapsToGIF(boolean value){}public void setExitOnFirstFatalError(boolean value){}public String exportDxl(Document doc){if(session.changeBetweenExports&&raw)doc.sequence++;return doc.dxl(raw);}public String getLog(){return session.fail?"<DXLLog><error>export failed</error></DXLLog>":"<DXLLog/>";}public void recycle(){recycled=true;}}
    public static class Session {boolean fail,changeBetweenExports;final List<Exporter> exporters=new ArrayList<>();public Exporter createDxlExporter(){var e=new Exporter(this);exporters.add(e);return e;}public String getEffectiveUserName(){return "CN=Loader/O=Acme";}}
    @Test void copiesValuesAndRecyclesOwnedExportersWithoutTouchingCallerDocument(){var session=new Session();var doc=new Document();var captured=new DominoImporter(session).capture(doc);assertEquals("captured",captured.text("Subject"));assertFalse(doc.recycled);assertEquals(2,session.exporters.size());assertTrue(session.exporters.stream().allMatch(e->e.recycled&&!e.attachmentsOmitted&&!e.picturesOmitted&&!e.oleOmitted));doc.recycle();assertEquals("captured",captured.text("Subject"));assertFalse(captured.rawDxl().isEmpty());assertEquals("REPLICA",captured.metadata().get("replicaid"));}
    @Test void detectsInconsistentDoubleExports(){var session=new Session();session.changeBetweenExports=true;assertThrows(DominoImportException.class,()->new DominoImporter(session).capture(new Document()));assertTrue(session.exporters.stream().allMatch(e->e.recycled));}
    @Test void reportsExportErrorsAndStillRecyclesExporter(){var session=new Session();session.fail=true;assertThrows(DominoImportException.class,()->new DominoImporter(session).capture(new Document()));assertTrue(session.exporters.get(0).recycled);}
    @Test void rejectsCrossThreadImport()throws Exception{var importer=new DominoImporter(new Session());var pool=Executors.newSingleThreadExecutor();try{var result=pool.submit(()->assertThrows(DominoImportException.class,()->importer.capture(new Document())));result.get();}finally{pool.shutdownNow();}}
    @Test void readsDesignCollectionsAndBinaryImageResources(){var captured=DominoImporter.readDesigns("<database><form name='Print'><body><richtext><par>Hello</par></richtext></body></form><imageresource name='logo.gif' alias='logo'><gif>AQID</gif></imageresource></database>",new PrintFormCompiler(new FormulaEngine()),List.of());assertEquals(1,captured.forms().size());assertArrayEquals(new byte[]{1,2,3},captured.resources().get("logo").bytes());assertEquals(captured.resources().get("logo"),captured.resources().get("logo.gif"));}
    @Test void opaqueImageResourcesArePreservedAndReported(){String dxl="<database><imageresource name='raw'><rawitemdata>AA==</rawitemdata></imageresource></database>";var captured=DominoImporter.readDesigns(dxl,new PrintFormCompiler(new FormulaEngine()),List.of());assertTrue(captured.resources().isEmpty());assertFalse(captured.diagnostics().isEmpty());assertEquals(dxl,captured.sourceDxl());}
}
